import{_ as d,l as n,o as e,c as i,v as o,p as l,x as t,d as s,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"换根 DP","description":"","frontmatter":{"title":"换根 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rerooting-dp.md","filePath":"cs/rerooting-dp.md","lastUpdated":1789023840000}'),h={name:"cs/rerooting-dp.md"};function u(_,a,D,P,m,f){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="换根-dp" tabindex="-1">换根 DP <a class="header-anchor" href="#换根-dp" aria-label="Permalink to &quot;换根 DP&quot;">​</a></h1><div class="epigraph"><p>先定根做一次树形 DP，再第二次 DFS 把「来自父亲的贡献」推到每个点，使每个顶点当根的答案 $O(n)$ 齐。</p><footer>—— 据树形 DP 二次扫描的标准技法；[树形 DP](/cs/tree-dp) 整理</footer></div><p>上一课<a href="/cs/plug-dp">插头 DP</a>在网格轮廓。树上一问「每个点当根时的最优/距离和」，朴素 \\(n\\) 次树 DP 是 \\(O(n^2)\\)。缺口是换根（rerooting）：一次下、一次上。不重写后序独立集。后课 LIS/LCS 换序列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>例：每个点到其它点的距离和。先以 \\(1\\) 为根算子树大小与子树内距离和；换到孩子 \\(v\\) 时，用 \\(n-2\\cdot sz[v]\\) 一类公式改距离和。一般：<code>up[v]</code> 表示除 \\(v\\) 子树外的信息，由父亲的 <code>up</code> 与兄弟合并。</p><p>缺口是第二次 DFS，不是点分治点对。</p><h3 id="合并要可减或可补" tabindex="-1">合并要可减或可补 <a class="header-anchor" href="#合并要可减或可补" aria-label="Permalink to &quot;合并要可减或可补&quot;">​</a></h3><p>若孩子贡献不能从总和里拆出（不可逆运算），换根要维护「去掉一个孩子」的结构，可能多 \\(\\log\\)。可结合、可删才 \\(O(n)\\)。</p><p><span class="marginnote">二次扫描是树 DP 标准。与点分治：换根给每个点当根的全局量；点分治给路径计数。后课 LIS 离开树。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一遍后序 <code>down[u]</code>。第二遍先序：用 <code>down</code> 与 <code>up[u]</code> 拼 <code>ans[u]</code>，再算每个孩子的 <code>up[v]</code>。兄弟前缀/后缀和便于 \\(O(deg)\\) 合计仍 \\(O(n)\\)。</p>',11)),(e(),l(c,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DWN%5B%22%E5%90%8E%E5%BA%8F%20down%22%5D%20--%3E%20UP%5B%22%E5%85%88%E5%BA%8F%E6%8E%A8%20up%22%5D%0A%20%20UP%20--%3E%20ANS%5B%22%E6%AF%8F%E4%B8%AA%E7%82%B9%E5%BD%93%E6%A0%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>换根公式先在纸上对一条边 \\((u,v)\\) 写清。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>树去边成两棵，信息在边上重接。与 HLD：HLD 管路径查询数据结构；换根是一次性全体根。与重心：重心是结构点，换根是答案平移。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写带修改换根。有环先缩点。后课默认：全体根上的树 DP 用二次 DFS。下一课 LIS 与 LCS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>下 DP + 上推父亲贡献 = 全体根 \\(O(n)\\)。</li><li>合并须能拆开一个孩子。</li><li>不是 \\(n\\) 次独立树 DP。</li><li>出处：树形 DP 二次扫描标准技法。</li></ul>',7))])}const E=d(h,[["render",u]]);export{A as __pageData,E as default};
